CREATE FUNCTION agri.forecast_iteration_evaluation(p_series_id uuid, p_as_of_time timestamp with time zone) RETURNS TABLE(iteration_id uuid, iteration_key character varying, series_id uuid, release_set_id uuid, cutoff_time timestamp with time zone, horizon_days integer, forecast_available_at timestamp with time zone, evaluated_count integer, actual_count integer, mean_absolute_error double precision, root_mean_squared_error double precision, interval_coverage double precision, receipt_checksum text, evaluation_checksum text)
    LANGUAGE sql STABLE
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, MDY'
    SET extra_float_digits TO '1'
    SET search_path TO 'public', 'pg_catalog'
    AS $$
    WITH gated AS (
        SELECT
            outcome.iteration_id,
            outcome.iteration_key,
            outcome.series_id,
            outcome.release_set_id,
            outcome.cutoff_time,
            outcome.horizon_days,
            outcome.forecast_available_at,
            outcome.receipt_checksum,
            outcome.actual_recorded_at,
            outcome.absolute_error,
            outcome.squared_error,
            outcome.interval_covered
        FROM agri.v_forecast_iteration_outcome AS outcome
        WHERE outcome.series_id = p_series_id
          AND outcome.forecast_available_at <= p_as_of_time
    ),
    aggregated AS (
        SELECT
            gated.iteration_id,
            gated.iteration_key,
            gated.series_id,
            gated.release_set_id,
            gated.cutoff_time,
            gated.horizon_days,
            gated.forecast_available_at,
            gated.receipt_checksum,
            count(*)::integer AS evaluated_count,
            count(*) FILTER (
                WHERE gated.actual_recorded_at IS NOT NULL
                  AND gated.actual_recorded_at <= p_as_of_time
            )::integer AS actual_count,
            avg(gated.absolute_error) FILTER (
                WHERE gated.actual_recorded_at IS NOT NULL
                  AND gated.actual_recorded_at <= p_as_of_time
            ) AS mean_absolute_error,
            sqrt(
                avg(gated.squared_error) FILTER (
                    WHERE gated.actual_recorded_at IS NOT NULL
                      AND gated.actual_recorded_at <= p_as_of_time
                )
            ) AS root_mean_squared_error,
            (avg(CASE WHEN gated.interval_covered THEN 1.0 ELSE 0.0 END) FILTER (
                WHERE gated.actual_recorded_at IS NOT NULL
                  AND gated.actual_recorded_at <= p_as_of_time
            ))::double precision AS interval_coverage
        FROM gated
        GROUP BY
            gated.iteration_id,
            gated.iteration_key,
            gated.series_id,
            gated.release_set_id,
            gated.cutoff_time,
            gated.horizon_days,
            gated.forecast_available_at,
            gated.receipt_checksum
    )
    SELECT
        aggregated.iteration_id,
        aggregated.iteration_key,
        aggregated.series_id,
        aggregated.release_set_id,
        aggregated.cutoff_time,
        aggregated.horizon_days,
        aggregated.forecast_available_at,
        aggregated.evaluated_count,
        aggregated.actual_count,
        aggregated.mean_absolute_error,
        aggregated.root_mean_squared_error,
        aggregated.interval_coverage,
        aggregated.receipt_checksum::text,
        encode(
            digest(
                concat_ws(
                    '|',
                    'forecast_iteration_evaluation_v1',
                    aggregated.iteration_id::text,
                    to_char(
                        p_as_of_time AT TIME ZONE 'UTC',
                        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
                    ),
                    aggregated.evaluated_count::text,
                    aggregated.actual_count::text,
                    aggregated.mean_absolute_error::text,
                    aggregated.root_mean_squared_error::text,
                    aggregated.interval_coverage::text
                ),
                'sha256'
            ),
            'hex'
        ) AS evaluation_checksum
    FROM aggregated
    ORDER BY aggregated.iteration_id
$$;
